begin;
create table if not exists public.platform_feature_flags(flag_key text primary key,name text not null,description text,default_enabled boolean not null default false,rollout_percentage integer not null default 100 check(rollout_percentage between 0 and 100),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.organization_feature_flag_overrides(organization_id uuid not null references public.organizations(id) on delete cascade,flag_key text not null references public.platform_feature_flags(flag_key) on delete cascade,enabled boolean not null,rollout_percentage integer check(rollout_percentage between 0 and 100),updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),primary key(organization_id,flag_key));
alter table public.platform_feature_flags enable row level security; alter table public.organization_feature_flag_overrides enable row level security;
create policy "authenticated read feature flags" on public.platform_feature_flags for select to authenticated using(true);
create policy "members read flag overrides" on public.organization_feature_flag_overrides for select using(exists(select 1 from public.organization_members m where m.organization_id=organization_feature_flag_overrides.organization_id and m.user_id=auth.uid()));
insert into public.platform_feature_flags(flag_key,name,description,default_enabled) values ('advanced_dashboards','Advanced dashboards','Saved and configurable enterprise dashboards',true),('usage_billing','Usage billing','Usage-based billing calculations and statements',true),('threat_detection','Threat detection','Automated security threat detection',true),('scheduled_exports','Scheduled exports','Durable scheduled reporting exports',true) on conflict(flag_key) do nothing;
commit;
